<script setup lang="ts">
import { ChevronDown, Heart, MapPin, Menu, Percent, Search, ShoppingCart, UserRound, X } from '@lucide/vue'
import type { StoreCategory, StoreTheme, StorefrontPayload } from '#shared/types/storefront'

const props = defineProps<{ storefront: StorefrontPayload, storeName: string, logoUrl?: string | null, categories: StoreCategory[], theme?: StoreTheme | null }>()
const menuOpen = ref(false)
const searchOpen = ref(false)
const search = ref('')
const { cart, wishlist, cartOpen, wishlistOpen, initialize } = useStorefrontCommerce(props.storefront)
const submitSearch = async () => {
  const term = search.value.trim()
  await navigateTo(term ? { path: '/produtos', query: { busca: term } } : '/produtos')
  searchOpen.value = false
}
onMounted(initialize)
</script>

<template>
  <div class="store-header">
    <div class="utility"><div class="header-container"><nav aria-label="Links auxiliares"><NuxtLink to="/conta">Minha conta</NuxtLink><NuxtLink to="/conta/pedidos">Acompanhar pedido</NuxtLink></nav><p>{{ theme?.header_message || 'Economize tempo. Encontre tudo para o seu cuidado.' }}</p><div><span>{{ theme?.service_hours || 'Atendimento diário' }}</span><strong>{{ theme?.contact_phone || '(11) 3000-1234' }}</strong></div></div></div>
    <header class="main-header header-container">
      <button class="mobile-menu" type="button" :aria-expanded="menuOpen" aria-label="Abrir menu" @click="menuOpen=!menuOpen"><X v-if="menuOpen" :size="21"/><Menu v-else :size="21"/></button>
      <NuxtLink to="/" class="brand"><img v-if="logoUrl" :src="logoUrl" :alt="storeName"><template v-else><span class="brand-symbol"></span><span><strong>{{ storeName }}</strong><small>cuidado todos os dias</small></span></template></NuxtLink>
      <form class="desktop-search join" @submit.prevent="submitSearch"><NuxtLink to="/categorias" class="category-select join-item">Categorias <ChevronDown :size="14"/></NuxtLink><label class="sr-only" for="pharmacy-search">Buscar produtos</label><input id="pharmacy-search" v-model="search" class="input join-item" placeholder="Busque por produtos, marcas ou sintomas"><button type="submit" class="btn btn-primary join-item" aria-label="Buscar"><Search :size="21"/></button></form>
      <div class="header-actions"><button class="location" type="button"><MapPin :size="21"/><span><small>Entregar em</small><strong>Informe seu CEP</strong></span></button><button class="icon-action search-trigger" type="button" aria-label="Buscar" @click="searchOpen=!searchOpen"><Search :size="20"/></button><NuxtLink class="icon-action" to="/conta" aria-label="Minha conta"><UserRound :size="21"/><span>Conta</span></NuxtLink><button class="icon-action favorite" type="button" aria-label="Abrir lista de desejos" @click="wishlistOpen=true"><Heart :size="21"/><span>Favoritos</span><b v-if="wishlist.length">{{ wishlist.length }}</b></button><button class="cart" type="button" aria-label="Abrir cesta" @click="cartOpen=true"><ShoppingCart :size="21"/><span>Cesta</span><b>{{ cart.totals.items_count }}</b></button></div>
    </header>
    <form v-if="searchOpen" class="mobile-search" @submit.prevent="submitSearch"><Search :size="18"/><input v-model="search" aria-label="Buscar produtos" placeholder="Busque por produtos ou marcas"><button class="btn btn-primary">Buscar</button></form>
    <nav class="category-nav" :class="{open:menuOpen}" aria-label="Navegação principal"><div class="header-container"><NuxtLink class="all-categories" to="/categorias"><Menu :size="17"/>Todas as categorias</NuxtLink><NuxtLink to="/produtos">Produtos</NuxtLink><NuxtLink v-for="category in categories.slice(0,4)" :key="category.id" :to="`/categoria/${category.slug}`">{{ category.name }}</NuxtLink><NuxtLink class="offers" to="/produtos"><Percent :size="16"/>Ofertas</NuxtLink></div></nav>
  </div>
</template>

